def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.28)
        return float(max(0.0, bid))

    opp_prev_bids = []
    desperate_count = 0
    rich_count = 0
    urgent_pressure = 0

    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= budget:
            rich_count += 1

        prev = opp.get('previous_trace', {})
        if prev:
            pbid = prev.get('bid')
            if pbid is not None:
                opp_prev_bids.append(float(pbid))
            if prev.get('status') == 'won':
                urgent_pressure += 1

    highest_prev = max(opp_prev_bids) if opp_prev_bids else 0.0
    avg_prev = sum(opp_prev_bids) / len(opp_prev_bids) if opp_prev_bids else 0.0

    base = DAILY_SALARY * 0.42

    if supply >= 23:
        base = DAILY_SALARY * 0.22
    elif supply >= 20:
        base = DAILY_SALARY * 0.32
    elif supply <= 16:
        base = DAILY_SALARY * 0.72
    elif supply <= 18:
        base = DAILY_SALARY * 0.56

    if hp <= 2 or no_water_days >= 2:
        bid = max(base, DAILY_SALARY * 0.96)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(base, DAILY_SALARY * 0.78)
    else:
        bid = base

    if highest_prev > 0:
        if highest_prev >= 120:
            if hp >= 6 and supply >= 19:
                bid = min(bid, DAILY_SALARY * 0.26)
            else:
                bid = max(bid, DAILY_SALARY * 0.74)
        elif highest_prev >= 90:
            if hp >= 7 and supply >= 20:
                bid = min(bid, DAILY_SALARY * 0.30)
            else:
                bid = max(bid, min(highest_prev * 0.72, DAILY_SALARY * 0.82))
        else:
            target = max(avg_prev + 2.0, DAILY_SALARY * 0.45)
            bid = max(bid, target)

    if desperate_count >= 2 and supply <= 18:
        bid = max(bid, DAILY_SALARY * 0.86)
    elif desperate_count == 0 and supply >= 20 and hp >= 6:
        bid = min(bid, DAILY_SALARY * 0.27)

    if rich_count >= 2 and hp >= 6 and supply >= 19:
        bid = min(bid, DAILY_SALARY * 0.34)

    if day >= 8:
        if hp >= 5:
            bid = min(bid, DAILY_SALARY * 0.38)
        else:
            bid = max(bid, DAILY_SALARY * 0.72)

    max_safe = budget
    if hp >= 6:
        reserve = max(0.0, (10 - day) * DAILY_SALARY * 0.18)
        max_safe = max(0.0, budget - reserve)
        if max_safe <= 0:
            max_safe = min(budget, DAILY_SALARY * 0.25)

    bid = min(bid, max_safe)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # Base survival urgency
    if hp <= 2 or no_water_days >= 2:
        urgency = 0.82
    elif hp <= 4:
        urgency = 0.68
    else:
        urgency = 0.58

    # React to yesterday's bids from alive opponents
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Compute a target bid band from yesterday
    target = None
    if prev_bids:
        # Approximate the opponent's typical “alive” bid band (Alex/Eric)
        # and “risky” lower band (David/Cindy).
        avg_bid = sum(prev_bids) / float(len(prev_bids))
        max_prev = max(prev_bids)
        # If someone bid high yesterday, they likely expect contention today.
        if max_prev >= DAILY_SALARY * 1.25:  # ~112.5
            # Slightly undercut to capture allocation if others overpay.
            target = min(DAILY_SALARY * 1.22, max(DAILY_SALARY * 0.95, avg_bid - 6.0))
        else:
            # If nobody was extreme, we can bid closer to the mid/high but not top.
            target = max(DAILY_SALARY * 0.85, avg_bid - 4.0)

    # Supply tightness adjustment: lower supply => higher chance others compete
    # Use a simple normalized factor.
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_t = 0.5
    # When supply is tight (low supply_t), increase bid slightly.
    tightness_boost = (1.0 - float(supply_t)) * 0.12

    if target is None:
        target = DAILY_SALARY * urgency
    else:
        target = target * (0.92 + tightness_boost)

    # Hard caps to avoid overspending: keep within budget and avoid bidding above a reasonable threshold.
    # If budget is low, bid proportionally.
    if budget <= 0:
        return 0.0

    # Convert target to a safe bid: at most 1.35*salary and at most 90% of budget.
    cap = min(budget, DAILY_SALARY * 1.35)
    bid = min(cap, target, budget * 0.9)

    # Ensure non-negative and keep at least a small amount if we must fight for survival.
    if bid < 0.0:
        bid = 0.0
    if bid == 0.0 and (hp <= 3 or no_water_days >= 2):
        bid = min(budget, DAILY_SALARY * 0.4)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    water_units = int(supply // WATER_REQ)  # convert to int
    budget = my_status['budget']
    hp = my_status['hp']
    no_water = my_status['no_water_days']

    alive = [o for o in opponents_status.values() if o['alive']]
    if not alive:
        return min(budget, DAILY_SALARY * 0.4)

    # collect previous bids from alive opponents
    prev_bids = []
    for opp in alive:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    if not prev_bids:
        # no info: default conservative
        if hp <= 2:
            target = DAILY_SALARY * 0.8
        else:
            target = DAILY_SALARY * 0.5
        return min(budget, target)

    max_prev = max(prev_bids)

    # Determine aggression level
    desperate = (hp <= 2) or (no_water >= 1)
    moderate = (3 <= hp <= 5)
    healthy = (hp > 5)

    if desperate:
        # bid enough to beat the highest previous, but cap at budget and high fraction of salary
        target = max(DAILY_SALARY * 0.8, max_prev + 1)
    elif moderate:
        # bid to beat the highest if it's not too high, otherwise be cautious
        if max_prev < DAILY_SALARY * 0.6:
            target = max(DAILY_SALARY * 0.5, max_prev + 1)
        else:
            # previous high is already high, consider saving
            target = DAILY_SALARY * 0.4
    else: # healthy
        # can afford to skip a round if everyone bids high
        if max_prev > DAILY_SALARY * 0.7:
            target = DAILY_SALARY * 0.3
        else:
            target = max(DAILY_SALARY * 0.35, max_prev + 1)

    return min(budget, target)
